class WebHostingNamespace(_Namespace):
    """The `web_hosting` business area."""

    @cached_property
    def control_panels(self) -> ControlPanelCollection:
        return ControlPanelCollection(self._session)

    @cached_property
    def dedibox_hostings(self) -> DediboxHostingCollection:
        return DediboxHostingCollection(self._session)

    @cached_property
    def domains(self) -> DomainCollection:
        return DomainCollection(self._session)

    @cached_property
    def free_root_domains(self) -> FreeRootDomainCollection:
        return FreeRootDomainCollection(self._session)

    @cached_property
    def hostings(self) -> HostingCollection:
        return HostingCollection(self._session)

    @cached_property
    def offers(self) -> OfferCollection:
        return OfferCollection(self._session)

    async def check_free_domain_availability(
        self,
        *,
        region: str | None = None,
        slug: str | None = None,
        root_domain: str | None = None,
    ) -> CheckFreeDomainAvailabilityResponse:
        """
        Check whether a given slug and free domain combination is available.
        """
        return await self._session.api(
            _WebhostingFreeDomainAPI
        ).check_free_domain_availability(
            region=region, slug=slug, root_domain=root_domain
        )

    async def search_domains(
        self,
        *,
        region: str | None = None,
        domain_name: str,
        project_id: str | _Ref[Any],
    ) -> SearchDomainsResponse:
        """
        Search for available domains based on domain name.
        """
        return await self._session.api(_WebhostingDnsAPI).search_domains(
            region=region, domain_name=domain_name, project_id=_identifier(project_id)
        )
